import { useCallback, useMemo, useState } from 'react';
import {
  CheckoutStep,
  CheckoutState,
  CartItem,
  Address,
  DeliveryMethod,
  PaymentMethod,
  CreditCard,
  BankTransfer,
  ValidationErrors,
} from './types';
import { INITIAL_ITEMS } from './data';
import StepIndicator from './components/StepIndicator';
import CartStep from './components/CartStep';
import DeliveryStep from './components/DeliveryStep';
import PaymentStep from './components/PaymentStep';
import ReviewStep from './components/ReviewStep';
import OrderSummary from './components/OrderSummary';

/* ========== Initial State ========== */

const EMPTY_ADDRESS: Address = {
  fullName: '',
  street: '',
  apt: '',
  city: '',
  state: '',
  zip: '',
  country: '',
  phone: '',
};

const EMPTY_CARD: CreditCard = {
  number: '',
  name: '',
  expiry: '',
  cvv: '',
};

const EMPTY_BANK: BankTransfer = {
  accountHolder: '',
  iban: '',
  bic: '',
};

function initialState(): CheckoutState {
  return {
    step: 'cart',
    items: INITIAL_ITEMS.map((i) => ({ ...i })),
    address: { ...EMPTY_ADDRESS },
    deliveryMethod: 'standard',
    paymentMethod: null,
    creditCard: { ...EMPTY_CARD },
    bankTransfer: { ...EMPTY_BANK },
    paypalEmail: '',
    errors: {},
    submitting: false,
    orderPlaced: false,
    orderId: null,
  };
}

/* ========== Validation ========== */

function validateCart(items: CartItem[]): ValidationErrors {
  const errs: ValidationErrors = {};
  if (items.length === 0) {
    errs['cart'] = 'Your cart is empty. Add at least one item to proceed.';
  }
  const outOfStock = items.find((i) => i.stock === 0);
  if (outOfStock) {
    errs['cart'] = `"${outOfStock.name}" is out of stock. Please remove it.`;
  }
  return errs;
}

function validateAddress(address: Address): ValidationErrors {
  const errs: ValidationErrors = {};
  if (!address.fullName.trim()) errs['fullName'] = 'Full name is required.';
  if (!address.street.trim()) errs['street'] = 'Street address is required.';
  if (!address.city.trim()) errs['city'] = 'City is required.';
  if (!address.state.trim()) errs['state'] = 'State / province is required.';
  if (!address.country) errs['country'] = 'Country is required.';
  if (!address.zip.trim()) {
    errs['zip'] = 'ZIP / postal code is required.';
  } else if (!/^[A-Za-z0-9\s\-]{3,10}$/.test(address.zip.trim())) {
    errs['zip'] = 'Please enter a valid ZIP / postal code.';
  }
  if (!address.phone.trim()) {
    errs['phone'] = 'Phone number is required.';
  } else if (!/^\+?[\d\s\-().]{7,20}$/.test(address.phone.trim())) {
    errs['phone'] = 'Please enter a valid phone number.';
  }
  return errs;
}

function validatePayment(
  paymentMethod: PaymentMethod | null,
  creditCard: CreditCard,
  bankTransfer: BankTransfer,
  paypalEmail: string,
): ValidationErrors {
  const errs: ValidationErrors = {};

  if (!paymentMethod) {
    errs['paymentMethod'] = 'Please select a payment method.';
    return errs;
  }

  if (paymentMethod === 'credit-card') {
    const cardNum = creditCard.number.replace(/\s/g, '');
    if (!cardNum) errs['cardNumber'] = 'Card number is required.';
    else if (!/^\d{13,19}$/.test(cardNum)) errs['cardNumber'] = 'Enter a valid card number (13–19 digits).';

    if (!creditCard.name.trim()) errs['cardName'] = 'Cardholder name is required.';

    if (!creditCard.expiry.trim()) {
      errs['expiry'] = 'Expiry date is required.';
    } else {
      const parts = creditCard.expiry.split('/');
      if (parts.length !== 2 || !/^\d{2}$/.test(parts[0]) || !/^\d{2}$/.test(parts[1])) {
        errs['expiry'] = 'Use MM/YY format.';
      } else {
        const month = parseInt(parts[0], 10);
        const year = parseInt(parts[1], 10) + 2000;
        const now = new Date();
        const expiryDate = new Date(year, month);
        if (month < 1 || month > 12) errs['expiry'] = 'Invalid month.';
        else if (expiryDate <= now) errs['expiry'] = 'This card has expired.';
      }
    }

    if (!creditCard.cvv.trim()) errs['cvv'] = 'CVV is required.';
    else if (!/^\d{3,4}$/.test(creditCard.cvv.trim())) errs['cvv'] = 'CVV must be 3 or 4 digits.';
  }

  if (paymentMethod === 'paypal') {
    if (!paypalEmail.trim()) errs['paypalEmail'] = 'PayPal email is required.';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(paypalEmail.trim()))
      errs['paypalEmail'] = 'Please enter a valid email address.';
  }

  if (paymentMethod === 'bank-transfer') {
    if (!bankTransfer.accountHolder.trim()) errs['accountHolder'] = 'Account holder name is required.';
    if (!bankTransfer.iban.trim()) {
      errs['iban'] = 'IBAN is required.';
    } else if (!/^[A-Z]{2}\d{2}[A-Z0-9]{11,30}$/.test(bankTransfer.iban.replace(/\s/g, '')))
      errs['iban'] = 'Enter a valid IBAN.';
    if (!bankTransfer.bic.trim()) {
      errs['bic'] = 'BIC / SWIFT is required.';
    } else if (!/^[A-Z]{6}[A-Z0-9]{2,5}$/.test(bankTransfer.bic.trim()))
      errs['bic'] = 'Enter a valid BIC/SWIFT code (8 or 11 characters).';
  }

  return errs;
}

/* ========== Main App ========== */

export default function App() {
  const [state, setState] = useState<CheckoutState>(initialState);

  const completedSteps = useMemo(() => {
    const set = new Set<CheckoutStep>();
    const order = ['cart', 'delivery', 'payment', 'review'] as CheckoutStep[];
    const currentIdx = order.indexOf(state.step);
    for (let i = 0; i < currentIdx; i++) {
      set.add(order[i]);
    }
    return set;
  }, [state.step]);

  /* ---- Cart actions ---- */
  const updateQuantity = useCallback((id: string, qty: number) => {
    setState((prev) => {
      const items = prev.items
        .map((item) => {
          if (item.id !== id) return item;
          const newQty = Math.max(1, Math.min(qty, item.stock));
          return { ...item, quantity: newQty };
        });
      return { ...prev, items, errors: {} };
    });
  }, []);

  const removeItem = useCallback((id: string) => {
    setState((prev) => {
      const items = prev.items.filter((item) => item.id !== id);
      return { ...prev, items, errors: {} };
    });
  }, []);

  /* ---- Address action ---- */
  const onAddressChange = useCallback((field: keyof Address, value: string) => {
    setState((prev) => ({
      ...prev,
      address: { ...prev.address, [field]: value },
      errors: {},
    }));
  }, []);

  /* ---- Delivery method ---- */
  const onDeliveryMethodChange = useCallback((method: DeliveryMethod) => {
    setState((prev) => ({ ...prev, deliveryMethod: method, errors: {} }));
  }, []);

  /* ---- Payment actions ---- */
  const onPaymentMethodChange = useCallback((method: PaymentMethod) => {
    setState((prev) => ({ ...prev, paymentMethod: method, errors: {} }));
  }, []);

  const onCreditCardChange = useCallback((field: keyof CreditCard, value: string) => {
    setState((prev) => ({
      ...prev,
      creditCard: { ...prev.creditCard, [field]: value },
      errors: {},
    }));
  }, []);

  const onBankTransferChange = useCallback((field: keyof BankTransfer, value: string) => {
    setState((prev) => ({
      ...prev,
      bankTransfer: { ...prev.bankTransfer, [field]: value },
      errors: {},
    }));
  }, []);

  const onPaypalEmailChange = useCallback((email: string) => {
    setState((prev) => ({ ...prev, paypalEmail: email, errors: {} }));
  }, []);

  /* ---- Step navigation with validation ---- */
  const goToStep = useCallback((step: CheckoutStep) => {
    setState((prev) => ({ ...prev, step, errors: {} }));
  }, []);

  const goToCart = () => goToStep('cart');
  const goToDelivery = () => {
    const errs = validateCart(state.items);
    if (Object.keys(errs).length > 0) {
      setState((prev) => ({ ...prev, errors: errs }));
      return;
    }
    goToStep('delivery');
  };

  const goToPayment = () => {
    const addrErrs = validateAddress(state.address);
    if (Object.keys(addrErrs).length > 0) {
      setState((prev) => ({ ...prev, errors: addrErrs }));
      return;
    }
    goToStep('payment');
  };

  const goToReview = () => {
    const payErrs = validatePayment(state.paymentMethod, state.creditCard, state.bankTransfer, state.paypalEmail);
    if (Object.keys(payErrs).length > 0) {
      setState((prev) => ({ ...prev, errors: payErrs }));
      return;
    }
    goToStep('review');
  };

  const placeOrder = useCallback(() => {
    setState((prev) => ({ ...prev, submitting: true }));
    // Simulate API call
    setTimeout(() => {
      const orderId = 'ORD-' + Date.now().toString(36).toUpperCase();
      setState((prev) => ({
        ...prev,
        submitting: false,
        orderPlaced: true,
        orderId,
      }));
    }, 2000);
  }, []);

  /* ---- Order placed screen ---- */
  if (state.orderPlaced) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
        <div className="max-w-md w-full bg-white rounded-2xl shadow-lg p-8 text-center">
          <div className="text-6xl mb-4">🎉</div>
          <h1 className="text-2xl font-bold text-gray-800 mb-2">Order Confirmed!</h1>
          <p className="text-gray-500 mb-6">
            Thank you for your purchase. Your order has been placed successfully.
          </p>
          <div className="bg-gray-50 rounded-xl p-4 mb-6">
            <p className="text-sm text-gray-500">Order Number</p>
            <p className="text-xl font-mono font-bold text-indigo-600">{state.orderId}</p>
          </div>
          <p className="text-sm text-gray-400 mb-6">
            A confirmation email will be sent shortly. You can track your order using the number above.
          </p>
          <button
            type="button"
            onClick={() => setState(initialState())}
            className="w-full py-3 bg-indigo-600 text-white font-semibold rounded-xl hover:bg-indigo-700 transition-colors"
          >
            Place Another Order
          </button>
        </div>
      </div>
    );
  }

  /* ---- Checkout Layout ---- */
  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white border-b border-gray-200">
        <div className="max-w-6xl mx-auto px-4 py-4 flex items-center justify-between">
          <h1 className="text-xl font-bold text-gray-800">🛍️ ShopCheckout</h1>
          <span className="text-sm text-gray-400">Secure Checkout</span>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 py-8">
        {/* Step Indicator */}
        <StepIndicator
          currentStep={state.step}
          onStepClick={goToStep}
          completedSteps={completedSteps}
        />

        {/* Two-column layout */}
        <div className="flex flex-col lg:flex-row gap-8">
          {/* Main content */}
          <div className="flex-1 min-w-0">
            {state.step === 'cart' && (
              <CartStep
                items={state.items}
                errors={state.errors}
                onUpdateQuantity={updateQuantity}
                onRemoveItem={removeItem}
                onNext={goToDelivery}
              />
            )}

            {state.step === 'delivery' && (
              <DeliveryStep
                address={state.address}
                deliveryMethod={state.deliveryMethod}
                errors={state.errors}
                onAddressChange={onAddressChange}
                onDeliveryMethodChange={onDeliveryMethodChange}
                onBack={goToCart}
                onNext={goToPayment}
              />
            )}

            {state.step === 'payment' && (
              <PaymentStep
                items={state.items}
                paymentMethod={state.paymentMethod}
                creditCard={state.creditCard}
                bankTransfer={state.bankTransfer}
                paypalEmail={state.paypalEmail}
                errors={state.errors}
                onPaymentMethodChange={onPaymentMethodChange}
                onCreditCardChange={onCreditCardChange}
                onBankTransferChange={onBankTransferChange}
                onPaypalEmailChange={onPaypalEmailChange}
                onBack={goToDelivery}
                onNext={goToReview}
              />
            )}

            {state.step === 'review' && (
              <ReviewStep
                items={state.items}
                address={state.address}
                deliveryMethod={state.deliveryMethod}
                paymentMethod={state.paymentMethod!}
                creditCard={state.creditCard}
                bankTransfer={state.bankTransfer}
                paypalEmail={state.paypalEmail}
                submitting={state.submitting}
                onBack={goToPayment}
                onPlaceOrder={placeOrder}
              />
            )}
          </div>

          {/* Sidebar */}
          <aside className="lg:w-80 shrink-0">
            <OrderSummary
              items={state.items}
              deliveryMethod={state.step === 'cart' ? null : state.deliveryMethod}
            />
          </aside>
        </div>
      </main>

      {/* Footer */}
      <footer className="border-t border-gray-200 mt-12 py-6 text-center text-sm text-gray-400">
        <p>🔒 Your data is encrypted and secure. We never store your full card details.</p>
      </footer>
    </div>
  );
}

