import { CartItem, ValidationErrors } from '../types';

interface Props {
  items: CartItem[];
  errors: ValidationErrors;
  onUpdateQuantity: (id: string, qty: number) => void;
  onRemoveItem: (id: string) => void;
  onNext: () => void;
}

export default function CartStep({ items, errors, onUpdateQuantity, onRemoveItem, onNext }: Props) {
  const handleNext = () => {
    onNext();
  };

  const cartError = errors['cart'];

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6">🛒 Your Cart</h2>

      {items.length === 0 ? (
        <div className="text-center py-16 text-gray-400">
          <p className="text-5xl mb-4">🛒</p>
          <p className="text-lg">Your cart is empty.</p>
          <p className="text-sm mt-1">Add some items to get started!</p>
        </div>
      ) : (
        <div className="space-y-4 mb-8">
          {items.map((item) => (
            <div
              key={item.id}
              className="flex items-center gap-4 p-4 bg-white border border-gray-200 rounded-xl hover:shadow-sm transition-shadow"
            >
              {/* Image placeholder */}
              <div className="w-16 h-16 bg-gray-100 rounded-lg flex items-center justify-center text-3xl shrink-0">
                {item.image}
              </div>

              {/* Info */}
              <div className="flex-1 min-w-0">
                <h4 className="font-semibold text-gray-800 truncate">{item.name}</h4>
                <p className="text-sm text-gray-500">${item.price.toFixed(2)} each</p>
                {item.stock === 0 && (
                  <p className="text-xs text-red-500 mt-0.5">Out of stock — will be removed</p>
                )}
                {item.stock > 0 && item.stock < 5 && (
                  <p className="text-xs text-amber-500 mt-0.5">Only {item.stock} left in stock</p>
                )}
              </div>

              {/* Quantity */}
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => onUpdateQuantity(item.id, item.quantity - 1)}
                  disabled={item.quantity <= 1}
                  className="w-8 h-8 rounded-full border border-gray-300 flex items-center justify-center text-gray-500 hover:bg-gray-100 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                  aria-label="Decrease quantity"
                >
                  −
                </button>
                <span className="w-10 text-center font-semibold text-gray-800 tabular-nums">
                  {item.quantity}
                </span>
                <button
                  type="button"
                  onClick={() => onUpdateQuantity(item.id, item.quantity + 1)}
                  disabled={item.quantity >= item.stock}
                  className="w-8 h-8 rounded-full border border-gray-300 flex items-center justify-center text-gray-500 hover:bg-gray-100 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                  aria-label="Increase quantity"
                >
                  +
                </button>
              </div>

              {/* Line total */}
              <span className="font-semibold text-gray-800 w-24 text-right tabular-nums">
                ${(item.price * item.quantity).toFixed(2)}
              </span>

              {/* Remove */}
              <button
                type="button"
                onClick={() => onRemoveItem(item.id)}
                className="text-gray-300 hover:text-red-500 transition-colors p-1"
                aria-label="Remove item"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                </svg>
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Error */}
      {cartError && (
        <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg text-sm text-red-700">
          ⚠️ {cartError}
        </div>
      )}

      {/* Action */}
      <div className="flex justify-end">
        <button
          type="button"
          onClick={handleNext}
          disabled={items.length === 0}
