import { useState } from 'react';
import {
  CartItem,
  PaymentMethod,
  CreditCard,
  BankTransfer,
  ValidationErrors,
  PaymentOption,
} from '../types';

interface Props {
  items: CartItem[];
  paymentMethod: PaymentMethod | null;
  creditCard: CreditCard;
  bankTransfer: BankTransfer;
  paypalEmail: string;
  errors: ValidationErrors;
  onPaymentMethodChange: (method: PaymentMethod) => void;
  onCreditCardChange: (field: keyof CreditCard, value: string) => void;
  onBankTransferChange: (field: keyof BankTransfer, value: string) => void;
  onPaypalEmailChange: (email: string) => void;
  onBack: () => void;
  onNext: () => void;
}

function formatCardNumber(value: string): string {
  const digits = value.replace(/\D/g, '').slice(0, 16);
  return digits.replace(/(\d{4})(?=\d)/g, '$1 ');
}

function formatExpiry(value: string): string {
  const digits = value.replace(/\D/g, '').slice(0, 4);
  if (digits.length > 2) return digits.slice(0, 2) + '/' + digits.slice(2);
  return digits;
}

export default function PaymentStep({
  items,
  paymentMethod,
  creditCard,
  bankTransfer,
  paypalEmail,
  errors,
  onPaymentMethodChange,
  onCreditCardChange,
  onBankTransferChange,
  onPaypalEmailChange,
  onBack,
  onNext,
}: Props) {
  const [touched, setTouched] = useState<Set<string>>(new Set());
  const orderTotal = items.reduce((s, i) => s + i.price * i.quantity, 0);

  // Dynamic payment options based on order total
  const paymentOptions: PaymentOption[] = [
    {
      id: 'credit-card',
      label: 'Credit / Debit Card',
      icon: '💳',
      enabled: true,
    },
    {
      id: 'paypal',
      label: 'PayPal',
      icon: '🅿️',
      enabled: true,
    },
    {
      id: 'bank-transfer',
      label: 'Bank Transfer',
      icon: '🏦',
      enabled: orderTotal >= 200,
      disabledReason: orderTotal < 200 ? 'Available for orders over $200' : undefined,
    },
    {
      id: 'apple-pay',
      label: 'Apple Pay',
      icon: '🍎',
      enabled: false,
      disabledReason: 'Coming soon',
    },
  ];

  const mark = (f: string) => setTouched((p) => new Set(p).add(f));

  const inputClass = (field: string) =>
    `w-full px-3 py-2.5 border rounded-lg text-sm outline-none transition-colors ${
      errors[field] && touched.has(field)
        ? 'border-red-400 bg-red-50'
        : 'border-gray-300 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500'
    }`;

  const labelClass = 'block text-sm font-medium text-gray-700 mb-1';

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6">💳 Payment Method</h2>

      {/* === Payment Method Selector === */}
      <div className="bg-white border border-gray-200 rounded-xl p-5 mb-6">
