  const shippingCost = deliveryOption?.basePrice ?? 0;
  const tax = Math.round(subtotal * 0.08 * 100) / 100;
  const total = Math.round((subtotal + shippingCost + tax) * 100) / 100;

  const paymentLabel: Record<PaymentMethod, string> = {
    'credit-card': 'Credit / Debit Card',
    'paypal': 'PayPal',
    'bank-transfer': 'Bank Transfer',
    'apple-pay': 'Apple Pay',
  };

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6">📋 Review Your Order</h2>

      {/* === Items === */}
      <div className="bg-white border border-gray-200 rounded-xl p-5 mb-4">
        <h3 className="text-base font-semibold text-gray-800 mb-3">Items ({items.length})</h3>
        <div className="space-y-2">
          {items.map((item) => (
            <div key={item.id} className="flex justify-between text-sm">
              <span className="text-gray-600">
                {item.image} {item.quantity}× {item.name}
              </span>
              <span className="text-gray-800 font-medium">
                ${(item.price * item.quantity).toFixed(2)}
              </span>
            </div>
          ))}
        </div>
      </div>

      {/* === Delivery === */}
      <div className="bg-white border border-gray-200 rounded-xl p-5 mb-4">
        <h3 className="text-base font-semibold text-gray-800 mb-3">Delivery</h3>
        <div className="text-sm space-y-1">
          <p className="text-gray-700 font-medium">
            {address.fullName}
          </p>
          <p className="text-gray-500">
            {address.street}
            {address.apt && `, ${address.apt}`}
          </p>
          <p className="text-gray-500">
            {address.city}, {address.state} {address.zip}
          </p>
          <p className="text-gray-500">{address.country}</p>
          <p className="text-gray-500">{address.phone}</p>
        </div>
        <div className="mt-3 pt-3 border-t border-gray-100">
          <p className="text-sm text-gray-700">
            <span className="font-medium">{deliveryOption?.label}</span> ·{' '}
            {deliveryOption?.estimatedDays}
            {shippingCost > 0 ? ` · $${shippingCost.toFixed(2)}` : ' · FREE'}
          </p>
        </div>
      </div>

      {/* === Payment === */}
      <div className="bg-white border border-gray-200 rounded-xl p-5 mb-4">
        <h3 className="text-base font-semibold text-gray-800 mb-3">Payment</h3>
        <p className="text-sm text-gray-700 font-medium">{paymentLabel[paymentMethod]}</p>

        {paymentMethod === 'credit-card' && (
          <div className="mt-2 text-sm text-gray-500">
            <p>{creditCard.name}</p>
            <p>•••• {creditCard.number.slice(-4)}</p>
            <p>Expires {creditCard.expiry}</p>
          </div>
        )}

        {paymentMethod === 'paypal' && (
          <p className="mt-2 text-sm text-gray-500">{paypalEmail}</p>
        )}

        {paymentMethod === 'bank-transfer' && (
          <div className="mt-2 text-sm text-gray-500">
            <p>{bankTransfer.accountHolder}</p>
            <p>IBAN: {bankTransfer.iban}</p>
            <p>BIC: {bankTransfer.bic}</p>
          </div>
        )}
      </div>

      {/* === Totals === */}
      <div className="bg-white border border-gray-200 rounded-xl p-5 mb-6">
        <h3 className="text-base font-semibold text-gray-800 mb-3">Order Total</h3>
        <div className="space-y-1 text-sm">
          <div className="flex justify-between">
            <span className="text-gray-500">Subtotal</span>
            <span className="text-gray-700">${subtotal.toFixed(2)}</span>
          </div>
          <div className="flex justify-between">
            <span className="text-gray-500">Shipping</span>
            <span className="text-gray-700">
              {shippingCost === 0 ? 'Free' : `$${shippingCost.toFixed(2)}`}
            </span>
          </div>
          <div className="flex justify-between">
            <span className="text-gray-500">Tax (8%)</span>
            <span className="text-gray-700">${tax.toFixed(2)}</span>
          </div>
          <hr className="my-2 border-gray-200" />
          <div className="flex justify-between text-base font-bold text-gray-900">
            <span>Total</span>
            <span>${total.toFixed(2)}</span>
          </div>
        </div>
      </div>

      {/* Navigation */}
      <div className="flex justify-between">
        <button
          type="button"
          onClick={onBack}
          disabled={submitting}
          className="px-6 py-3 border border-gray-300 text-gray-700 font-semibold rounded-xl hover:bg-gray-50 disabled:opacity-50 transition-colors"
        >
          ← Back to Payment
        </button>
        <button
          type="button"
          onClick={onPlaceOrder}
          disabled={submitting}
          className="px-10 py-3 bg-emerald-600 text-white font-bold rounded-xl hover:bg-emerald-700 disabled:bg-gray-300 disabled:cursor-not-allowed transition-colors shadow-sm flex items-center gap-2"
        >
          {submitting ? (
            <>
              <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24" fill="none">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
              </svg>
              Processing...
            </>
          ) : (
            'Place Order ✓'
          )}
        </button>
      </div>
    </div>
  );
}

