import { CheckoutStep, STEPS } from '../types';

interface Props {
  currentStep: CheckoutStep;
  onStepClick: (step: CheckoutStep) => void;
  completedSteps: Set<CheckoutStep>;
}

export default function StepIndicator({ currentStep, onStepClick, completedSteps }: Props) {
  const currentIdx = STEPS.findIndex((s) => s.id === currentStep);

  return (
    <nav className="flex items-center justify-center gap-0 mb-8" aria-label="Checkout progress">
      {STEPS.map((step, i) => {
        const isActive = step.id === currentStep;
        const isDone = completedSteps.has(step.id);
        const isClickable = isDone || (i <= currentIdx);

        let circleClass =
          'w-9 h-9 rounded-full flex items-center justify-center text-sm font-bold border-2 transition-all duration-200 shrink-0';
        if (isDone) {
          circleClass += ' bg-emerald-500 border-emerald-500 text-white';
        } else if (isActive) {
          circleClass += ' bg-indigo-600 border-indigo-600 text-white ring-4 ring-indigo-200';
        } else {
          circleClass += ' bg-gray-100 border-gray-300 text-gray-400';
        }

        return (
          <div key={step.id} className="flex items-center gap-0">
            {i > 0 && (
              <div
                className={`h-0.5 w-10 sm:w-16 transition-colors duration-300 ${
                  completedSteps.has(STEPS[i - 1].id) ? 'bg-emerald-400' : 'bg-gray-200'
                }`}
              />
            )}
            <button
              type="button"
              disabled={!isClickable}
              onClick={() => isClickable && onStepClick(step.id)}
              className="flex flex-col items-center gap-1 group"
              aria-current={isActive ? 'step' : undefined}
            >
              <span className={circleClass}>
                {isDone ? '✓' : step.number}
              </span>
              <span
                className={`text-xs font-medium transition-colors ${
                  isActive
                    ? 'text-indigo-700'
                    : isDone
                      ? 'text-emerald-600'
                      : 'text-gray-400'
                }`}
              >
                {step.label}
              </span>
            </button>
          </div>
        );
      })}
    </nav>
  );
}

