import { useState } from 'react';
import type { Address, DeliveryMethod, ValidationErrors } from '../types';
import { DELIVERY_OPTIONS, COUNTRIES, STATES_BY_COUNTRY } from '../data';

interface Props {
  address: Address;
  deliveryMethod: DeliveryMethod;
  errors: ValidationErrors;
  onAddressChange: (field: keyof Address, value: string) => void;
  onDeliveryMethodChange: (method: DeliveryMethod) => void;
  onBack: () => void;
  onNext: () => void;
}

export default function DeliveryStep({
  address,
  deliveryMethod,
  errors,
  onAddressChange,
  onDeliveryMethodChange,
  onBack,
  onNext,
}: Props) {
  const [touched, setTouched] = useState<Set<string>>(new Set());

  const states = STATES_BY_COUNTRY[address.country] || [];
  const isInternational = address.country && address.country !== 'United States';

  // Dynamic delivery options based on country
  const availableOptions = DELIVERY_OPTIONS.map((opt) => {
    if (opt.id === 'pickup' && isInternational) {
      return { ...opt, basePrice: -1 }; // disabled
    }
    if (opt.id === 'express' && isInternational) {
      return { ...opt, basePrice: 34.99, estimatedDays: '3–5 business days' };
    }
    if (opt.id === 'standard' && isInternational) {
      return { ...opt, basePrice: 14.99, estimatedDays: '7–14 business days' };
    }
    return opt;
  });

  const mark = (field: string) => setTouched((prev) => new Set(prev).add(field));

  const fieldClass = (field: string, extra = '') =>
    `w-full px-3 py-2.5 border rounded-lg text-sm transition-colors outline-none ${extra} ${
      errors[field] && touched.has(field)
        ? 'border-red-400 bg-red-50'
        : 'border-gray-300 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500'
    }`;

  const labelClass = 'block text-sm font-medium text-gray-700 mb-1';

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6">📦 Delivery Details</h2>

      {/* === Address Form === */}
      <div className="bg-white border border-gray-200 rounded-xl p-5 mb-6">
        <h3 className="text-lg font-semibold text-gray-800 mb-4">Shipping Address</h3>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {/* Full Name */}
          <div className="sm:col-span-2">
            <label className={labelClass}>Full Name *</label>
            <input
              type="text"
              value={address.fullName}
              onChange={(e) => onAddressChange('fullName', e.target.value)}
              onBlur={() => mark('fullName')}
              placeholder="John Doe"
              className={fieldClass('fullName')}
            />
            {errors['fullName'] && touched.has('fullName') && (
              <p className="text-xs text-red-500 mt-1">{errors['fullName']}</p>
            )}
          </div>

          {/* Street */}
          <div className="sm:col-span-2">
            <label className={labelClass}>Street Address *</label>
            <input
              type="text"
              value={address.street}
              onChange={(e) => onAddressChange('street', e.target.value)}
              onBlur={() => mark('street')}
              placeholder="123 Main Street"
              className={fieldClass('street')}
            />
            {errors['street'] && touched.has('street') && (
              <p className="text-xs text-red-500 mt-1">{errors['street']}</p>
            )}
          </div>

          {/* Apt */}
          <div className="sm:col-span-2">
            <label className={labelClass}>Apartment / Suite (optional)</label>
            <input
              type="text"
              value={address.apt}
              onChange={(e) => onAddressChange('apt', e.target.value)}
              placeholder="Apt 4B"
              className={fieldClass('apt')}
            />
          </div>

          {/* Country */}
          <div>
            <label className={labelClass}>Country *</label>
            <select
              value={address.country}
              onChange={(e) => onAddressChange('country', e.target.value)}
              onBlur={() => mark('country')}
              className={fieldClass('country')}
            >
              <option value="">Select country</option>
              {COUNTRIES.map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </select>
            {errors['country'] && touched.has('country') && (
              <p className="text-xs text-red-500 mt-1">{errors['country']}</p>
            )}
          </div>

          {/* State */}
          <div>
            <label className={labelClass}>State / Province *</label>
            {states.length > 0 ? (
              <select
                value={address.state}
                onChange={(e) => onAddressChange('state', e.target.value)}
                onBlur={() => mark('state')}
                className={fieldClass('state')}
              >
                <option value="">Select state</option>
                {states.map((s) => (
                  <option key={s} value={s}>
                    {s}
                  </option>
                ))}
              </select>
            ) : (
              <input
                type="text"
                value={address.state}
                onChange={(e) => onAddressChange('state', e.target.value)}
                onBlur={() => mark('state')}
                placeholder="Enter state/province"
                className={fieldClass('state')}
              />
            )}
            {errors['state'] && touched.has('state') && (
              <p className="text-xs text-red-500 mt-1">{errors['state']}</p>
            )}
          </div>

          {/* City */}
          <div>
            <label className={labelClass}>City *</label>
            <input
              type="text"
              value={address.city}
              onChange={(e) => onAddressChange('city', e.target.value)}
              onBlur={() => mark('city')}
              placeholder="San Francisco"
              className={fieldClass('city')}
            />
            {errors['city'] && touched.has('city') && (
              <p className="text-xs text-red-500 mt-1">{errors['city']}</p>
            )}
          </div>

          {/* ZIP */}
          <div>
            <label className={labelClass}>ZIP / Postal Code *</label>
            <input
              type="text"
              value={address.zip}
              onChange={(e) => onAddressChange('zip', e.target.value)}
              onBlur={() => mark('zip')}
              placeholder="94102"
              className={fieldClass('zip')}
            />
            {errors['zip'] && touched.has('zip') && (
              <p className="text-xs text-red-500 mt-1">{errors['zip']}</p>
            )}
          </div>

          {/* Phone */}
          <div className="sm:col-span-2">
            <label className={labelClass}>Phone Number *</label>
            <input
              type="tel"
              value={address.phone}
              onChange={(e) => onAddressChange('phone', e.target.value)}
              onBlur={() => mark('phone')}
              placeholder="+1 (555) 123-4567"
              className={fieldClass('phone')}
            />
            {errors['phone'] && touched.has('phone') && (
              <p className="text-xs text-red-500 mt-1">{errors['phone']}</p>
            )}
          </div>
        </div>
      </div>

      {/* === Delivery Method === */}
      <div className="bg-white border border-gray-200 rounded-xl p-5 mb-6">
        <h3 className="text-lg font-semibold text-gray-800 mb-4">Delivery Method</h3>

        {isInternational && (
          <div className="mb-4 p-3 bg-amber-50 border border-amber-200 rounded-lg text-sm text-amber-700">
            🌍 International shipping — delivery times and costs vary by destination.
          </div>
        )}

        <div className="space-y-3">
          {availableOptions.map((opt) => {
            const isUnavailable = opt.basePrice < 0;
            const isSelected = deliveryMethod === opt.id;
            const priceLabel =
              opt.basePrice === 0 ? 'FREE' : isUnavailable ? 'N/A' : `$${opt.basePrice.toFixed(2)}`;

            return (
              <label
                key={opt.id}
                className={`flex items-start gap-3 p-4 border-2 rounded-xl cursor-pointer transition-all ${
                  isUnavailable
                    ? 'border-gray-200 bg-gray-50 opacity-50 cursor-not-allowed'
                    : isSelected
                      ? 'border-indigo-500 bg-indigo-50'
                      : 'border-gray-200 hover:border-indigo-300'
                }`}
              >
                <input
                  type="radio"
                  name="delivery"
                  value={opt.id}
                  checked={isSelected}
                  disabled={isUnavailable}
                  onChange={() => onDeliveryMethodChange(opt.id)}
                  className="mt-0.5 accent-indigo-600"
                />
                <div className="flex-1">
                  <div className="flex items-center justify-between">
                    <span className="font-semibold text-gray-800">{opt.label}</span>
                    <span
                      className={`font-bold text-sm ${
                        opt.basePrice === 0 ? 'text-emerald-600' : 'text-gray-700'
                      }`}
                    >
                      {priceLabel}
                    </span>
                  </div>
                  <p className="text-sm text-gray-500 mt-0.5">
                    {opt.description} · <span className="font-medium">{opt.estimatedDays}</span>
                  </p>
                  {isUnavailable && (
                    <p className="text-xs text-red-500 mt-1">
                      In-store pickup is only available for domestic orders.
                    </p>
                  )}
                </div>
              </label>
            );
          })}
        </div>
      </div>

      {/* Global delivery error */}
      {errors['deliveryMethod'] && (
        <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg text-sm text-red-700">
          ⚠️ {errors['deliveryMethod']}
        </div>
      )}

      {/* Navigation */}
      <div className="flex justify-between">
        <button
          type="button"
          onClick={onBack}
          className="px-6 py-3 border border-gray-300 text-gray-700 font-semibold rounded-xl hover:bg-gray-50 transition-colors"
        >
          ← Back to Cart
        </button>
        <button
          type="button"
          onClick={onNext}
          className="px-8 py-3 bg-indigo-600 text-white font-semibold rounded-xl hover:bg-indigo-700 transition-colors shadow-sm"
        >
          Continue to Payment →
        </button>
      </div>
    </div>
  );
}

