import type { CartItem, DeliveryMethod } from '../types';
import { DELIVERY_OPTIONS } from '../data';

interface Props {
  items: CartItem[];
  deliveryMethod: DeliveryMethod | null;
}

export default function OrderSummary({ items, deliveryMethod }: Props) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const deliveryOption = deliveryMethod
    ? DELIVERY_OPTIONS.find((o) => o.id === deliveryMethod)
    : null;
  const shippingCost = deliveryOption?.basePrice ?? 0;
  const tax = Math.round(subtotal * 0.08 * 100) / 100;
  const total = Math.round((subtotal + shippingCost + tax) * 100) / 100;

  return (
    <div className="bg-gray-50 border border-gray-200 rounded-xl p-5 sticky top-4">
      <h3 className="text-base font-semibold text-gray-800 mb-4">Order Summary</h3>

      {/* Item Lines */}
      <div className="space-y-3 mb-4">
        {items.map((item) => (
          <div key={item.id} className="flex justify-between text-sm">
            <span className="text-gray-600 truncate pr-2 flex-1">
              {item.quantity}× {item.name}
            </span>
            <span className="text-gray-800 font-medium whitespace-nowrap">
              ${(item.price * item.quantity).toFixed(2)}
            </span>
          </div>
        ))}
      </div>

      <hr className="border-gray-200 mb-4" />

      {/* Calculations */}
      <div className="space-y-2 text-sm">
        <div className="flex justify-between">
          <span className="text-gray-500">Subtotal</span>
          <span className="text-gray-700">${subtotal.toFixed(2)}</span>
        </div>
        <div className="flex justify-between">
          <span className="text-gray-500">Shipping</span>
          <span className="text-gray-700">
            {deliveryOption ? (shippingCost === 0 ? 'Free' : `$${shippingCost.toFixed(2)}`) : '—'}
          </span>
        </div>
        <div className="flex justify-between">
          <span className="text-gray-500">Tax (8%)</span>
          <span className="text-gray-700">${tax.toFixed(2)}</span>
        </div>
      </div>

      <hr className="border-gray-200 my-4" />

      <div className="flex justify-between text-base font-bold text-gray-900">
        <span>Total</span>
        <span>${total.toFixed(2)}</span>
      </div>

      {/* Promo hint */}
      <div className="mt-4 p-3 bg-indigo-50 border border-indigo-100 rounded-lg text-xs text-indigo-700">
        💡 Free shipping on orders over $500
      </div>
    </div>
  );
}

