import { useState } from 'react';
import type {
  CartItem,
  PaymentMethod,
  CreditCard,
  BankTransfer,
  ValidationErrors,
  PaymentOption,
} from '../types';

interface Props {
  items: CartItem[];
  paymentMethod: PaymentMethod | null;
  creditCard: CreditCard;
  bankTransfer: BankTransfer;
  paypalEmail: string;
  errors: ValidationErrors;
  onPaymentMethodChange: (method: PaymentMethod) => void;
  onCreditCardChange: (field: keyof CreditCard, value: string) => void;
  onBankTransferChange: (field: keyof BankTransfer, value: string) => void;
  onPaypalEmailChange: (email: string) => void;
  onBack: () => void;
  onNext: () => void;
}

function formatCardNumber(value: string): string {
  const digits = value.replace(/\D/g, '').slice(0, 16);
  return digits.replace(/(\d{4})(?=\d)/g, '$1 ');
}

function formatExpiry(value: string): string {
  const digits = value.replace(/\D/g, '').slice(0, 4);
  if (digits.length > 2) return digits.slice(0, 2) + '/' + digits.slice(2);
  return digits;
}

export default function PaymentStep({
  items,
  paymentMethod,
  creditCard,
  bankTransfer,
  paypalEmail,
  errors,
  onPaymentMethodChange,
  onCreditCardChange,
  onBankTransferChange,
  onPaypalEmailChange,
  onBack,
  onNext,
}: Props) {
  const [touched, setTouched] = useState<Set<string>>(new Set());
  const orderTotal = items.reduce((s, i) => s + i.price * i.quantity, 0);

  // Dynamic payment options based on order total
  const paymentOptions: PaymentOption[] = [
    {
      id: 'credit-card',
      label: 'Credit / Debit Card',
      icon: '💳',
      enabled: true,
    },
    {
      id: 'paypal',
      label: 'PayPal',
      icon: '🅿️',
      enabled: true,
    },
    {
      id: 'bank-transfer',
      label: 'Bank Transfer',
      icon: '🏦',
      enabled: orderTotal >= 200,
      disabledReason: orderTotal < 200 ? 'Available for orders over $200' : undefined,
    },
    {
      id: 'apple-pay',
      label: 'Apple Pay',
      icon: '🍎',
      enabled: false,
      disabledReason: 'Coming soon',
    },
  ];

  const mark = (f: string) => setTouched((p) => new Set(p).add(f));

  const inputClass = (field: string) =>
    `w-full px-3 py-2.5 border rounded-lg text-sm outline-none transition-colors ${
      errors[field] && touched.has(field)
        ? 'border-red-400 bg-red-50'
        : 'border-gray-300 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500'
    }`;

  const labelClass = 'block text-sm font-medium text-gray-700 mb-1';

  return (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6">💳 Payment Method</h2>

      {/* === Payment Method Selector === */}
      <div className="bg-white border border-gray-200 rounded-xl p-5 mb-6">
        <h3 className="text-lg font-semibold text-gray-800 mb-4">Choose a payment method</h3>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {paymentOptions.map((opt) => (
            <label
              key={opt.id}
              className={`flex items-center gap-3 p-4 border-2 rounded-xl transition-all ${
                !opt.enabled
                  ? 'border-gray-200 bg-gray-50 opacity-50 cursor-not-allowed'
                  : paymentMethod === opt.id
                    ? 'border-indigo-500 bg-indigo-50'
                    : 'border-gray-200 hover:border-indigo-300 cursor-pointer'
              }`}
            >
              <input
                type="radio"
                name="payment"
                value={opt.id}
                checked={paymentMethod === opt.id}
                disabled={!opt.enabled}
                onChange={() => onPaymentMethodChange(opt.id)}
                className="accent-indigo-600"
              />
              <div>
                <span className="font-semibold text-gray-800 text-sm">
                  {opt.icon} {opt.label}
                </span>
                {!opt.enabled && opt.disabledReason && (
                  <p className="text-xs text-gray-400 mt-0.5">{opt.disabledReason}</p>
                )}
              </div>
            </label>
          ))}
        </div>
      </div>

      {/* === Credit Card Form === */}
      {paymentMethod === 'credit-card' && (
        <div className="bg-white border border-gray-200 rounded-xl p-5 mb-6 animate-[fadeIn_0.2s_ease]">
          <h3 className="text-lg font-semibold text-gray-800 mb-4">Card Details</h3>

          <div className="space-y-4">
            {/* Card Number */}
            <div>
              <label className={labelClass}>Card Number *</label>
              <input
                type="text"
                inputMode="numeric"
                value={creditCard.number}
                onChange={(e) =>
                  onCreditCardChange('number', formatCardNumber(e.target.value))
                }
                onBlur={() => mark('cardNumber')}
                placeholder="1234 5678 9012 3456"
                maxLength={19}
                className={inputClass('cardNumber')}
              />
              {errors['cardNumber'] && touched.has('cardNumber') && (
                <p className="text-xs text-red-500 mt-1">{errors['cardNumber']}</p>
              )}
            </div>

            {/* Card Name */}
            <div>
              <label className={labelClass}>Cardholder Name *</label>
              <input
                type="text"
                value={creditCard.name}
                onChange={(e) => onCreditCardChange('name', e.target.value)}
                onBlur={() => mark('cardName')}
                placeholder="John Doe"
                className={inputClass('cardName')}
              />
              {errors['cardName'] && touched.has('cardName') && (
                <p className="text-xs text-red-500 mt-1">{errors['cardName']}</p>
              )}
            </div>

            {/* Expiry + CVV */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className={labelClass}>Expiry Date *</label>
                <input
                  type="text"
                  inputMode="numeric"
                  value={creditCard.expiry}
                  onChange={(e) =>
                    onCreditCardChange('expiry', formatExpiry(e.target.value))
                  }
                  onBlur={() => mark('expiry')}
                  placeholder="MM/YY"
                  maxLength={5}
                  className={inputClass('expiry')}
                />
                {errors['expiry'] && touched.has('expiry') && (
                  <p className="text-xs text-red-500 mt-1">{errors['expiry']}</p>
                )}
              </div>
              <div>
                <label className={labelClass}>CVV *</label>
                <input
                  type="text"
                  inputMode="numeric"
                  value={creditCard.cvv}
                  onChange={(e) =>
                    onCreditCardChange('cvv', e.target.value.replace(/\D/g, '').slice(0, 4))
                  }
                  onBlur={() => mark('cvv')}
                  placeholder="123"
                  maxLength={4}
                  className={inputClass('cvv')}
                />
                {errors['cvv'] && touched.has('cvv') && (
                  <p className="text-xs text-red-500 mt-1">{errors['cvv']}</p>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* === PayPal Form === */}
      {paymentMethod === 'paypal' && (
        <div className="bg-white border border-gray-200 rounded-xl p-5 mb-6 animate-[fadeIn_0.2s_ease]">
          <h3 className="text-lg font-semibold text-gray-800 mb-4">PayPal Account</h3>
          <p className="text-sm text-gray-500 mb-4">
            You'll be redirected to PayPal to complete your payment after reviewing your order.
          </p>
          <div>
            <label className={labelClass}>PayPal Email *</label>
            <input
              type="email"
              value={paypalEmail}
              onChange={(e) => onPaypalEmailChange(e.target.value)}
              onBlur={() => mark('paypalEmail')}
              placeholder="you@example.com"
              className={inputClass('paypalEmail')}
            />
            {errors['paypalEmail'] && touched.has('paypalEmail') && (
              <p className="text-xs text-red-500 mt-1">{errors['paypalEmail']}</p>
            )}
          </div>
        </div>
      )}

      {/* === Bank Transfer Form === */}
      {paymentMethod === 'bank-transfer' && (
        <div className="bg-white border border-gray-200 rounded-xl p-5 mb-6 animate-[fadeIn_0.2s_ease]">
          <h3 className="text-lg font-semibold text-gray-800 mb-4">Bank Transfer Details</h3>
          <div className="space-y-4">
            <div>
              <label className={labelClass}>Account Holder Name *</label>
              <input
                type="text"
                value={bankTransfer.accountHolder}
                onChange={(e) => onBankTransferChange('accountHolder', e.target.value)}
                onBlur={() => mark('accountHolder')}
                placeholder="John Doe"
                className={inputClass('accountHolder')}
              />
              {errors['accountHolder'] && touched.has('accountHolder') && (
                <p className="text-xs text-red-500 mt-1">{errors['accountHolder']}</p>
              )}
            </div>
            <div>
              <label className={labelClass}>IBAN *</label>
              <input
                type="text"
                value={bankTransfer.iban}
                onChange={(e) => onBankTransferChange('iban', e.target.value.toUpperCase())}
                onBlur={() => mark('iban')}
                placeholder="DE89 3704 0044 0532 0130 00"
                className={inputClass('iban')}
              />
              {errors['iban'] && touched.has('iban') && (
                <p className="text-xs text-red-500 mt-1">{errors['iban']}</p>
              )}
            </div>
            <div>
              <label className={labelClass}>BIC / SWIFT *</label>
              <input
                type="text"
                value={bankTransfer.bic}
                onChange={(e) => onBankTransferChange('bic', e.target.value.toUpperCase())}
                onBlur={() => mark('bic')}
                placeholder="COBADEFFXXX"
                className={inputClass('bic')}
              />
              {errors['bic'] && touched.has('bic') && (
                <p className="text-xs text-red-500 mt-1">{errors['bic']}</p>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Global payment error */}
      {errors['paymentMethod'] && (
        <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg text-sm text-red-700">
          ⚠️ {errors['paymentMethod']}
        </div>
      )}

      {/* Navigation */}
      <div className="flex justify-between">
        <button
          type="button"
          onClick={onBack}
          className="px-6 py-3 border border-gray-300 text-gray-700 font-semibold rounded-xl hover:bg-gray-50 transition-colors"
        >
          ← Back to Delivery
        </button>
        <button
          type="button"
          onClick={onNext}
          className="px-8 py-3 bg-indigo-600 text-white font-semibold rounded-xl hover:bg-indigo-700 transition-colors shadow-sm"
        >
          Review Order →
        </button>
      </div>
    </div>
  );
}

